	title 'Memory Peeker Desk Accessory'********************************************************************************** Memory Peeker** by Rich Williams May 1986** This is a classic	DA that displays the memory lists* This is not part of the memory manager at all and is included because* there is extra room** Rev 2 changes* 1) Shutdown call added (just an RTL)*** Change History** ?? ??? ??	Rich Williams** Added shutdown call for version 2.0 of rom.*** 23 Aug 88	Steven Glass** Separated this code from memory manager.* Changed way lists are paused and interrupted.**********************************************************************************	include 'all.macros'	include 'mm.equates.asm';-----------------------------------------------------------;; These are variables used in zero page; the DA manager saves and restores zero page for us;;; Note that the order of the variables after the event record; is very important.  The code that draws the handle relys on the; buffer being 5 bytes past MyCount.  It also relys on Ptr being; only 3 bytes long.;	DSect $80EventRecord	word EventMessage	longEventWhen	longEventWhere	longEventMods	wordEventType	equ EventRecordEventKey	equ EventMessageMycount	wordPtr	block 3buffer	block HSizeMyDelta	longMyTotal	longline	longptr2	equ Buffer+hndl_next*****************************************************************InstallPeekerDA	PROC EXPORT** This is the code that installs the peeker desk accessory.**** Inputs:*	none** Outputs:*	none** External Refs:	import Peeker	import PeekerID** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	longa on	longi on	if DebugVersion then	lda #0	tcd	jsl Peeker	_Quit QuitParamsQuitParams	dc.L 0,0	ENDIF	rep #$30	;Make sure 16 bits	PushLong #PeekerID	_InstallCDA	rtl	ENDP*****************************************************************Peeker	PROC** This is the code that runs the DA.*** Inputs:*	none** Outputs:*	none** External Refs:	import Freeze	import ReadKey	import B3	import PrintThisLine	import DoLine** Entry Points:*	none*	longa on	; mode	longi on******************************************************************* First initialize the output to the screen*	pea 0	;Get Output device	pea 0	pea 0	_GetOutputDevice	pea 0	pea 0	_GetOutGlobals	pea $00FF	pea $0080	_SetOutGlobals	pea $0000	pushlong #00000003	_SetOutputDevice	pea 0	_InitTextDev	pea 1	_InitTextDevDoTrace	rep #$30	PushLong #Prompt	;Print the prompt line	_WriteLineGetKey	jsr ReadKey	and #$007F	;Force upper case &	high byte clear	cmp #'a'	bcc Upper	eor #$0020Upper	cmp #'U'	beq UList	;Used list	cmp #'P'	beq PList	;Purged list	cmp #'F'	beq FList	;Free list	cmp #'Q'	;Quit	bne GetKey	;Invalid character.	 Go get anotherDone	rep #$30	_SetOutGlobals	;Restore the globals	_SetOutputDevice	;Set the output device	ENTRY PeekerRTLPeekerRTL		;       ;Shut down call does nothing	rtl	;Back to the DA managerUList	ldx #0	;Memlist	bra doitPList	ldx #4	;EmptyList	bra doitFList	ldx #8	;FreeList	bra doitdoit		; 	php	;Save interrupt status	lda >MeMList,x	;Get the list to do	sta Ptr	lda >MemList+2,x	sta Ptr+2	stz mycount	;Handle count	stz MyTotal	;Free space	stz MyTotal+2	pushlong #TitleLine	_WriteLine	sep #$30	longa off	longi offprloop		jsr Freeze	bcs NoTotal	lda ptr	;Nil pointer?	ora ptr+1	ora ptr+2	bne NotDone	;Br if not nil	lda MyTotal	;If total = 0 don't	print it	ora MyTotal+1	ora MyTotal+3	beq NoTotal	ldx #60	;Print the total free spaceMoveTotal	lda >TotalLine,x	sta Line,x	dex	bpl MoveTotal	ldx #MyTotal-MyCount	jsr b3	jsr DoLineNoTotal	plp	;Restore int status	jmp Dotrace	;Done with list. Go	prompt for anotherNotDone	stz line	;New line	ldy #Hsize-1	;Move the info from	the handle into ZPmvloop	lda [ptr],y	tyx	sta Buffer,x	dey	bpl mvloop	jsr PrintThisLine	bra prloop;-----------------------------------------------------------;; Header lines used above.;Prompt	dc.b 50	dc.b 'U= Used list  P= Purge list  F= Free list  Q= Quit'TitleLine	dc.b 52,$8D,$8D	dc.b '#    Handle  Addr  Attr  ID    Size    Prev   Next'TotalLine	dc.b 53,$8D	dc.b '                                  Total Free Memory ='	dc.b '        '	ENDP*****************************************************************PrintThisLine	PROC** This is the routine that prints the contents of the* handle in buffer.  It also prints the free space between* this handle and the next (if there is any.*** Inputs:*	Buffer contains the handle to print*	MyCount contains the number of this handle** Outputs:*	PTR is updated to point to the next handle.** External Refs:*	none** Entry Points:	ENTRY B3	ENTRY DoLine** Called in 8 bit native mode!	longa off	; mode	longi off*****************************************************************	rep #$20	longa on	stz MyDelta	;MyDelta = free space after block	stz MyDelta+2	lda ptr2	ora ptr2+2	;Nil?	beq NoDelta	ldy #2	;Addr of next can't	be 0	lda [ptr2]	ora [ptr2],y	beq NoDelta	lda [ptr2]	;Calc free space after block	sec	sbc [ptr]	sta MyDelta	lda [ptr2],y	sbc [ptr],y	sta MyDelta+2	lda MyDelta	sec	sbc Buffer+hndl_size	sta MyDelta	lda MyDelta+2	sbc Buffer+hndl_size+2	sta MyDelta+2	lda MyDelta	;Add to total	clc	adc MyTotal	sta MyTotal	lda MyDelta+2	adc MyTotal+2	sta MyTotal+2NoDelta	inc MyCount	;Inc handle count	sep #$30	longa off	longi off* Now print out the	info from the handle	ldx #0	;Handle #	jsr b2	ldx #2	;Handle address	jsr b3	ldx #Hndl_Addr+5	;Block address	jsr b3	ldx #Hndl_Attr+5	;Attributes	jsr b2	ldx #Hndl_Owner+5	;Owner	jsr b2	ldx #Hndl_Size+5	;Size	jsr b4	ldx #Hndl_Prev+5	;Pointer to previous	jsr B3	ldx #Hndl_Next+5	;Pointer to next	jsr B3	jsr DoLine	;Print the line	lda MyDelta	;Any Delta?	ora MyDelta+1	ora MyDelta+2	beq NoDelta2	rep #$30	;for the free space, figure where it starts	longa on	longi on	lda Buffer+Hndl_Addr	clc	adc Buffer+Hndl_Size	sta Buffer+Hndl_Addr	lda Buffer+Hndl_Addr+2	adc Buffer+Hndl_Size+2	sta Buffer+Hndl_Addr+2	lda Buffer+Hndl_Addr	bne @NoCarry	lda Buffer+Hndl_Addr+2@NoCarry	lda MyDelta	;and how big it is	sta Buffer+Hndl_Size	lda MyDelta+2	sta Buffer+Hndl_Size+2	sep #$30	longa off	longi off	ldy #4+1+6+1	jsr blanks	ldx #Hndl_Addr+5	;Block address	jsr b3	ldy #1+4+4+1	jsr blanks		ldx #Hndl_Size+5	;Size	jsr b4	jsr DoLine	;Print the lineNoDelta2	ldx #3	;Go to the next handlemvlp2	lda Ptr2,x	sta Ptr,x	dex	bpl mvlp2	rts;-----------------------------------------------------------;; Code that prints the parts of the handle.  On entry,; the x-reg holds the offset from MyCount of the item; to print.;; After an item is printed, a blank is printed.;b4	phx	;Print 4 byte number	lda mycount+3,x	jsr prbyte	plxb3	phx	;Print 3 byte number	lda mycount+2,x	jsr prbyte	plxb2	phx	;Print 2 byte number	lda mycount+1,x	jsr prbyte	plxb1	lda mycount,x	;Print 1 byte number	jsr prbyte	jsr prblnk	;Print a blank	rts;-----------------------------------------------------------;; Puts a hex byte in the output buffer.;prbyte	pha	lsr A	lsr A	lsr A	lsr A	jsr prbyte2	pla	and #$0Fprbyte2 	ora #$B0	cmp #$BA	bcc cout	adc #6cout	ldx line	;Put char in output	buffer	sta line+1,x	inc line	rts;-----------------------------------------------------------;; Puts the number of blanks passed in the y-reg into; the output buffer.;Blanks	cpy #0	beq @Done@again	jsr prblnk	dey	bne @again@done	rts;-----------------------------------------------------------;; Puts one blank in the output buffer.;prblnk		;Prints a blank	lda #$A0	bra cout;-----------------------------------------------------------;; Actually prints the line buffer and zeros the line ; size countDoLine	rep #$30	;Print the line	longa on	longi on	PushLong #Line	_WriteLine	sep #$30	longa off	longi off	stz Line	;Line index set to 0 for new line	rts	ENDP*****************************************************************PeekerID	PROC** This is the data that defines a classic desk accessory.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DC.L PeekerName	; pointer to real id section.	dc.w 0	; just in case someone wants to lock usPeekerName	str 'Memory Peeker'	; da name	DC.L Peeker	; pointer to peeker routine	DC.L PeekerRTL	; pointer to ShutDown call	ENDP*****************************************************************ReadKey	PROC** Reads key from keyboard using the event manager or* the hardware (as necessary).*** Inputs:*	none** Outputs:*	a-reg   the key read** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;; First try using the event manager;Again	pha	; space for result	PushWord #$FFFF	; all events	PushLong #EventRecord	_GetNextEvent	bcs ReadItMyself	pla	beq Again	lda EventType	cmp #3	; key down	beq GotAKey	cmp #5	; auto key down	bne AgainGotAKey	lda EventKey	rtsReadItMyself		; 	pla	sep #%00110000Loop	lda >$E0C000	bpl Loop	sta >$E0C010	rep #%00110000	and #$007F	rts	ENDPKeyDown	PROC; if the event manager is active i need	to get keys from; it.	PushWord #0	; space for result	PushWord #%0000000000101000	PushLong #EventRecord	_EventAvail	bcs ReadItMyself	pla	beq NoKeyDown	bra YesKeyDownReadItMyself		; 	pla	sep #%00110000Loop	lda >$E0C000	rep #%00110000	bpl NoKeyDownYesKeyDown	sec	rtsNoKeyDown	clc	rts	ENDP*****************************************************************Freeze	PROC** This routine looks at the keyboard.  If there is a key pending* it reads it.  If the key is ESCAPE, we report done* If it is not escape, we wait for another key.  If that one* is ESCAPE, we report done.  Otherwise we report not done.*** Inputs:*	none** Outputs:*	carry clear = not done*	carry set   = done** External Refs:	import ReadKey	import KeyDown** Entry Points:*	none*** Wow!   This is called in 8bit native mode. and it returns that* way.*	longa off	; mode	longi off*****************************************************************	php	; save mode	rep #$30	longa on	longi on	jsr KeyDown	bcc Done	jsr ReadKey	; clear this key	cmp #27	; if esc then signal quit	beq Quit	jsr ReadKey	; Wait for next key	cmp #27	; if esc then signal quit	bne Done Quit	plp	sec	rtsDone	plp	clc	rts	ENDP	END